CREATE TABLE module_registry (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, module_key VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'inactive', navigation_path VARCHAR(190) NULL, permission_namespace VARCHAR(64) NOT NULL UNIQUE, CHECK(status IN ('active','inactive'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
